// Prototype rules, not trained probabilities. Laugh has its own score/threshold semantics.
export const classifierPolicy=Object.freeze({laughEnter:.65,laughExit:.5,mouthRange:[.25,.65],openingJaw:[.15,.55],openingGeometry:[.08,.28],eyeRange:[.1,.5],maxSideWeight:.6})
const smooth=(x,a,b)=>{const t=Math.max(0,Math.min(1,(x-a)/(b-a)));return t*t*(3-2*t)}
export function laughEvidence(raw,context,config){const v=raw.values,p=context?.pose,valid=!p?.available||p.valid&&Math.abs(p.yaw)<=55&&Math.abs(p.pitch)<=40;if(!valid)return{score:0,reason:'unsupported pose',policy:classifierPolicy};const yaw=p?.valid?Math.abs(p.yaw):0,side=v.mouthSmileLeft>=v.mouthSmileRight?'Left':'Right',other=side==='Left'?'Right':'Left',weight=smooth(yaw,10,40)*classifierPolicy.maxSideWeight,mean=(v.mouthSmileLeft+v.mouthSmileRight)/2,mouth=mean*(1-weight)+v['mouthSmile'+side]*weight,eyeMean=(v.eyeSquintLeft+v.eyeSquintRight)/2,eye=eyeMean*(1-weight)+v['eyeSquint'+side]*weight,inhibition=1-smooth(Math.max(v.mouthFunnel,v.mouthPucker),.1,.35),smile=smooth(mouth,.25,.65)*smooth(v['mouthSmile'+other],.03,.18)*inhibition,jaw=smooth(v.jawOpen,.15,.55),geometry=Number.isFinite(context?.mouthOpenness)?smooth(context.mouthOpenness,.08,.28):null,opening=geometry===null?jaw:Math.min(1,.6*jaw+.4*geometry),support=smooth(eye,.1,.5),openScore=Math.min(smile,opening,support);
 // Existing well-supported closed grins remain compatible; high mouth alone is insufficient.
 const closedSupported=raw.smileIntensity>=config.laughEnter&&raw.cheekScore>=.25&&raw.eyeSquintScore>=.15,closedScore=closedSupported?.8:0;
 return{score:Math.max(openScore,closedScore),smileEvidence:smile,openingEvidence:opening,eyeEvidence:support,openScore,closedScore,rawMouth:mean,finalMouth:mouth,side,sideWeight:weight,jawEvidence:jaw,geometryEvidence:geometry,poseValid:valid,reason:'open laugh = minimum of smile, opening and eye evidence; P0-1 gain is not reapplied',policy:classifierPolicy}}
